export const clamp=(n,min=0,max=100)=>Math.max(min,Math.min(max,n));
export function initialState(){return {version:1,month:0,term:1,money:850,pop:1240,econ:0,green:0,eco:68,equality:58,services:59,tax:0.014,investment:0,subsidy:0,flags:[],actions:3,decision:0,policyIndex:0,ended:false,election:null,history:[],seed:7319,buildings:[{type:'house',x:4,y:3},{type:'house',x:5,y:3},{type:'house',x:7,y:3},{type:'house',x:8,y:3},{type:'house',x:4,y:5},{type:'tower',x:5,y:5},{type:'shop',x:7,y:5},{type:'shop',x:8,y:5},{type:'park',x:4,y:7},{type:'clinic',x:5,y:7},{type:'house',x:7,y:7},{type:'office',x:8,y:7}],log:[{month:0,title:'Um novo capítulo para Aurora',text:'Você tomou posse. Escolha sua primeira política e comece a construir.',kind:'info'}],lastEvent:null};}
export function metrics(s){
 const totals=s.buildings.reduce((a,b)=>{const d=BUILDINGS[b.type];a.housing+=d.housing;a.jobs+=d.jobs;a.cost+=d.maintenance;return a;},{housing:350,jobs:60,cost:9});
 const jobs=Math.max(0,totals.jobs+s.investment),workers=s.pop*.52;
 const employment=clamp(jobs/workers*100),housing=clamp(totals.housing/s.pop*100);
 const quality=clamp(18+s.services*.31+s.eco*.19+employment*.2+housing*.11-(s.pop>totals.housing?8:0));
 const income=s.pop*s.tax+Math.min(jobs,workers)*.035+Math.max(0,s.econ)*.025;
 const costs=totals.cost+s.subsidy+s.pop*.004;
 const groups={families:clamp(quality*.45+s.equality*.35+housing*.2-Math.max(0,35-s.equality)*.6),business:clamp(employment*.45+45+s.econ*.24-s.tax*900),greens:clamp(s.eco*.72+20+s.green*.2)};
 const approval=clamp(groups.families*.5+groups.business*.3+groups.greens*.2-(s.money<0?12:0));
 return {...totals,jobs,employment,quality,income,costs,balance:income-costs,groups,approval};
}
export function identity(s){if(s.econ < -18 && s.green>15)return 'Ecossocial';if(s.econ>18&&s.green>15)return 'Mercado verde';if(s.econ < -18)return 'Solidária';if(s.econ>18)return 'Empreendedora';if(s.green>18)return 'Sustentável';if(s.green < -18)return 'Desenvolvimentista';return 'Plural';}
export function isLand(x,y){return Number.isInteger(x)&&Number.isInteger(y)&&x>=3&&x<=10&&y>=1&&y<=10&&x!==6&&y!==4&&y!==8;}
export function addLog(s,title,text,kind='info'){s.log.unshift({month:s.month,title,text,kind});s.log=s.log.slice(0,60);}
export function build(s,type,x,y){const d=BUILDINGS[type];if(s.ended)return 'Este mandato terminou.';if(!d)return 'Construção inválida.';if(d.unlock&&!d.unlock(s))return d.requirement;if(!isLand(x,y)||s.buildings.some(b=>b.x===x&&b.y===y))return 'Escolha um terreno livre fora das ruas e do rio.';if(s.actions<=0)return 'Limite de 3 obras por mês. Avance o mês.';if(s.money<d.cost)return 'Saldo insuficiente para esta construção.';s.money-=d.cost;s.actions--;s.buildings.push({type,x,y});s.eco=clamp(s.eco+d.eco);s.equality=clamp(s.equality+d.equality);if(type==='clinic')s.services=clamp(s.services+7);s.green=clamp(s.green+(type==='forest'?5:type==='park'?3:0),-100,100);addLog(s,d.name+' inaugurado',`Investimento de R$ ${d.cost} mil. ${d.jobs} novos postos de trabalho.`,'build');return null;}
export function decide(s,index){if(s.ended)return 'Este mandato terminou.';if(s.decision===null)return 'Nenhuma decisão pendente.';const p=POLICIES[s.decision],c=p.choices[index];if(!c)return 'Opção inválida.';for(const [key,v] of Object.entries(c.effects)){if(key==='flag'){if(!s.flags.includes(v))s.flags.push(v);}else s[key]+=v;}for(const k of ['eco','equality','services'])s[k]=clamp(s[k]);s.econ=clamp(s.econ,-100,100);s.green=clamp(s.green,-100,100);s.tax=clamp(s.tax,.005,.04);s.subsidy=Math.max(0,s.subsidy);s.history.push({month:s.month,econ:s.econ,green:s.green,title:c.title});addLog(s,c.title,c.body,'policy');s.policyIndex++;s.decision=null;return null;}
function random(s){s.seed=(s.seed*1664525+1013904223)>>>0;return s.seed/4294967296;}
export function advance(s){if(s.ended)return 'Este mandato terminou.';if(s.decision!==null)return 'Seu gabinete aguarda uma decisão antes de avançar.';const m=metrics(s);s.month++;s.actions=3;s.money+=m.balance;const growth=Math.round((m.quality-42)*1.2+(m.employment-75)*.8);s.pop=Math.max(350,Math.min(m.housing+180,s.pop+growth));s.services=clamp(s.services+(s.buildings.filter(b=>b.type==='clinic').length*1250>=s.pop?.15:-.45));s.eco=clamp(s.eco-(s.pop>2100?.7:.25)+(s.green>30?.3:0));s.equality=clamp(s.equality+(m.employment>95?.2:-.4));s.lastEvent=null;
 if(s.month%5===0){const r=random(s);if(s.eco<50){const cost=Math.round(35+(50-s.eco));s.money-=cost;s.services=clamp(s.services-3);s.lastEvent={title:'O calor cobrou seu preço',text:`Pouca cobertura verde aumentou os gastos de saúde em R$ ${cost} mil. Parques e reservas reduzem a vulnerabilidade.`,kind:'warning'};}else if(s.equality<40){s.money-=25;s.investment=Math.max(0,s.investment-20);s.lastEvent={title:'Protestos por uma cidade acessível',text:'A desigualdade provocou protestos. O comércio perdeu movimento e a prefeitura gastou R$ 25 mil.',kind:'warning'};}else if(r>.48){s.money+=50;s.lastEvent={title:'Aurora atrai novos visitantes',text:'O bom momento da cidade movimentou o comércio. R$ 50 mil extras entraram no caixa.',kind:'good'};}else {s.money-=30;s.lastEvent={title:'Manutenção fora do planejado',text:'As chuvas danificaram a rede de drenagem. O reparo custou R$ 30 mil.',kind:'warning'};}addLog(s,s.lastEvent.title,s.lastEvent.text,s.lastEvent.kind);}
 if(s.money < -160){s.ended=true;s.election={won:false,title:'A cidade entrou em intervenção',text:'O déficit ultrapassou R$ 160 mil. Seu mandato termina com uma crise fiscal.'};return null;}
 if(s.month%48===0){const approval=metrics(s).approval;s.election={won:approval>=50,title:approval>=50?'Aurora escolheu continuar.':'Aurora escolheu uma mudança.',text:`Você recebeu ${Math.round(approval)}% de apoio. ${approval>=50?'Sua gestão conquistou mais quatro anos.':'Era preciso alcançar 50% para conquistar um novo mandato.'}`};s.ended=true;addLog(s,s.election.title,s.election.text,'election');return null;}
 if(s.month%3===0)s.decision=s.policyIndex%POLICIES.length;return null;}
export function continueTerm(s){if(!s.election?.won)return false;s.term++;s.ended=false;s.election=null;s.decision=s.policyIndex%POLICIES.length;addLog(s,'Um novo mandato começa','As políticas e o legado do mandato anterior continuam em vigor.','election');return true;}
export function validSave(s){return !!s&&s.version===1&&Number.isInteger(s.month)&&s.month>=0&&s.month<=4800&&['term','money','pop','econ','green','eco','equality','services','tax','investment','subsidy','actions','policyIndex','seed'].every(k=>Number.isFinite(s[k]))&&typeof s.ended==='boolean'&&(!s.ended||(!!s.election&&typeof s.election.won==='boolean'&&typeof s.election.title==='string'&&typeof s.election.text==='string'))&&Array.isArray(s.flags)&&s.flags.every(f=>typeof f==='string')&&Array.isArray(s.history)&&s.history.every(h=>typeof h.title==='string'&&Number.isFinite(h.month)&&Number.isFinite(h.econ)&&Number.isFinite(h.green))&&Array.isArray(s.log)&&s.log.every(l=>typeof l.title==='string'&&typeof l.text==='string'&&Number.isFinite(l.month))&&(s.decision===null||Number.isInteger(s.decision)&&s.decision>=0&&s.decision<POLICIES.length)&&Array.isArray(s.buildings)&&s.buildings.length<=100&&s.buildings.every(b=>BUILDINGS[b.type]&&isLand(b.x,b.y))&&new Set(s.buildings.map(b=>`${b.x},${b.y}`)).size===s.buildings.length;}
